{

"kind": "propose",
"summary": "Raise CPU limit for container 'api' in Deployment 'search' to 750m to alleviate throttling causing readiness probe failures.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Container 'api' is throttled 81% of the time at 500m limit, causing CPU-bound latency and readiness probe timeouts.",
    "supporting": ["ev-container_logs_tail", "ev-target_events"],
    "contradicting": ["cpu_throttled_at_limit", "cpu_usage_near_limit"],
    "missing": ["container_logs_tail.throttled_usec.details"],
    "status": "open"
  },
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "Recent revision 2 may use more CPU than previous version 1, despite similar limits, causing throttling.",
    "supporting": ["ev-revision_health", "ev-rollout_history"],
    "contradicting": ["throttling_came_with_rollout"],
    "missing": ["revision_health.throttledRatio.history"],
    "status": "open"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search", "uid": "uid-deployment-search"},
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raises CPU limit to 750m, reducing throttling and allowing application to meet readiness probe deadlines.",
  "rationale": "Logs show 81% throttling at 500m limit, matching readiness failures. Increasing limit to 1.5x current value (750m) should clear throttling without risking node CPU contention, as node-level contention isn't indicated in evidence.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-target_events", "ev-container_cpu", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "throttling_came_with_rollout"]
}
}
